import React from "react";

import { Grid, Card, CardContent } from "@mui/material";

import Hr from "../../common/Hr/index.jsx";
import FeatureList from "../../common/FeatureList";

import '../../pages/Products/DomesticProducts/style.css';

const TrinityRange = () => {

    const TrinityRange = [
        {
            img: require("../../assets/Products/DomesticRange/TheTrinityRange/img-1.png"),
            name: "KC-1003",
            alt: "KC-1003",
        },
        {
            img: require("../../assets/Products/DomesticRange/TheTrinityRange/img-2.png"),
            name: "KC-2003",
            alt: "KC-2003",
        },
        {
            img: require("../../assets/Products/DomesticRange/TheTrinityRange/img-3.png"),
            name: "KC-3003",
            alt: "KC-3003",
        }
    ]
    return (
        <>
            <Grid container spacing={2} className="the-signature-range">
                <Grid item xs={12} sm={12} md={12} lg={12} className="domestic-products-grid">
                    <Card className="domestic-products-card"  >
                        <CardContent className="domestic-products-card-content">
                            <h5 className="domestic-products-card-h5" data-aos="fade-up" data-aos-duration="500">
                                The Trinity Range
                            </h5>
                            <div className="domestic-products-card-image-div-container">
                                {
                                    TrinityRange.map((item, index) => {
                                        return (
                                            <>
                                                <Grid item xs={12} sm={12} md={4} lg={4}
                                                    sx={{
                                                        transition: '0.3s',
                                                        '&:hover': {
                                                            transform: 'scale(1.03)',
                                                            boxShadow: '0 4px 20px rgba(0,0,0,0.1)',
                                                        },
                                                    }}
                                                >
                                                    <div
                                                        className="domestic-products-card-image-div"
                                                        key={index} data-aos="zoom-in"
                                                        data-aos-duration="500"
                                                    >
                                                        <div className="domestic-products-card-image-div-1">
                                                            <img
                                                                src={item.img}
                                                                alt={item.alt || 'Trinity Range'}
                                                                className="single-burner-range-image"
                                                            />
                                                        </div>
                                                        <h6 className="domestic-products-name-h6">
                                                            {item.name}
                                                        </h6>
                                                    </div>
                                                </Grid>
                                            </>
                                        )
                                    })
                                }
                            </div>
                            <Hr />
                            <FeatureList
                                title={"Features"}
                                features={[
                                    "JOINTLESS STAINLESS STEEL BODY",
                                    "HIGH EFFICIENCY BRASS BURNERS",
                                    "SMOOTH OPERATING KNOBS",
                                    'EASY CLEANING & MAINTENANCE',
                                    'SLIM DESIGN',
                                    'PERFECT BLUE FLAME',
                                ]}
                            />
                        </CardContent>
                    </Card>
                </Grid>
            </Grid>
        </>
    )
}
export default TrinityRange;